    ["<Assistant_Title1>Clash! Honorary Knighthood</>\n<Assistant_Title2>Achievement Category: </>Battle for Growth - Competition\n<Assistant_Title2>Unlock Condition: </>Reach Duke rank in Dominator's Clash"] = "<Assistant_Title1>Схватка! Посвящение в рыцари</>\n<Assistant_Title2>Категория достижения: </>Война питает войну — Состязание\n<Assistant_Title2>Условие открытия: </>Достичь ранга «Герцог» в режиме «Борьба владык»",
    ["Appearance"] = "Появление",
    ["Derrick's Greatsword"] = "Большой меч Деррика",
